// Aplatit la réponse Supabase et revalide l'URL (sécurité : elle part dans une commande shell)
const IG = /^https:\/\/www\.instagram\.com\/(reel|p|tv)\/[A-Za-z0-9_-]+\/$/;
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const rows = Array.isArray(j) ? j : Array.isArray(j?.data) ? j.data : [j];
  for (const r of rows) {
    if (!r || !r.id || !IG.test(r.url || '')) continue;
    out.push({ json: { id: r.id, household_id: r.household_id, chat_id: r.chat_id, url: r.url, attempts: r.attempts } });
  }
}
return out;

// Rassemble légende + transcription et prépare l'appel de mise en forme
const job = $('Liste des imports').item.json;
const dl = $('Télécharger (yt-dlp)').item.json;
let meta = {};
const lines = String(dl.stdout || '').split('\n').map(l => l.trim()).filter(l => l.startsWith('{'));
if (lines.length) { try { meta = JSON.parse(lines[lines.length - 1]); } catch (e) {} }

const transcript = typeof $json.text === 'string' ? $json.text.trim() : '';
const caption = String(meta.description || '').trim();
if (!transcript && !caption) {
  throw new Error('NOT_RECIPE: ni description ni son exploitable dans cette vidéo');
}

const SYSTEM = "Tu es un chef et assistant culinaire. On te donne la description (légende) et la transcription audio d'une vidéo Instagram. Tu en extrais UNE recette complète, structurée, en français.\n\nRègles :\n- Si la source est dans une autre langue, traduis tout en français.\n- N'invente pas d'ingrédient absent de la source. Si une quantité n'est pas donnée, quantity = null.\n- Quantités en nombres décimaux (0.5 et pas \"1/2\"). Convertis les unités US (cup, oz, lb, tbsp, tsp) en métrique (g, ml, cas, cac).\n- unit : \"piece\" pour ce qui se compte (2 œufs → quantity 2, unit \"piece\"), \"\" si aucune unité n'a de sens (ex : \"sel\" sans quantité).\n- name : nom court tel qu'on l'achète, sans quantité, en minuscules (ex : \"oignon jaune\", \"crème fraîche épaisse\"). Les précisions de préparation vont dans note (ex : \"émincé\", \"à température ambiante\").\n- section : rayon de supermarché le plus logique pour l'ingrédient.\n- steps : étapes claires, à l'impératif, dans l'ordre, sans numérotation. Intègre les températures et durées de cuisson.\n- Si non précisés, estime de façon réaliste : servings (2 par défaut), prep_minutes, cook_minutes (null si aucune cuisson), difficulty.\n- diets : uniquement les régimes réellement compatibles avec TOUS les ingrédients (ex : \"vegetarien\" seulement s'il n'y a ni viande ni poisson).\n- title : nom de plat appétissant et précis, sans emoji. description : 1 à 2 phrases donnant envie.\n- tips : astuces ou variantes mentionnées dans la source, sinon \"\".\n- Si le contenu n'est clairement pas une recette de cuisine, is_recipe = false (remplis le reste au minimum).";
const SCHEMA = {"type": "object", "additionalProperties": false, "required": ["is_recipe", "title", "description", "category", "difficulty", "servings", "prep_minutes", "cook_minutes", "diets", "ingredients", "steps", "tips"], "properties": {"is_recipe": {"type": "boolean"}, "title": {"type": "string"}, "description": {"type": "string"}, "category": {"type": "string", "enum": ["entree", "plat", "dessert", "petit_dejeuner", "aperitif", "accompagnement", "sauce", "boisson", "autre"]}, "difficulty": {"type": "string", "enum": ["facile", "moyen", "difficile"]}, "servings": {"type": "integer"}, "prep_minutes": {"type": ["integer", "null"]}, "cook_minutes": {"type": ["integer", "null"]}, "diets": {"type": "array", "items": {"type": "string", "enum": ["vegetarien", "vegan", "pescetarien", "sans_gluten", "sans_lactose", "leger", "proteine"]}}, "ingredients": {"type": "array", "items": {"type": "object", "additionalProperties": false, "required": ["name", "quantity", "unit", "section", "note"], "properties": {"name": {"type": "string"}, "quantity": {"type": ["number", "null"]}, "unit": {"type": "string", "enum": ["", "g", "kg", "ml", "cl", "l", "cac", "cas", "piece", "pincee", "gousse", "tranche", "botte", "sachet", "boite", "tasse"]}, "section": {"type": "string", "enum": ["fruits_legumes", "boucherie", "poissonnerie", "cremerie", "charcuterie_traiteur", "boulangerie", "feculents", "conserves", "condiments", "epices", "epicerie_sucree", "petit_dejeuner", "biscuits_aperitif", "surgeles", "boissons", "monde", "autre"]}, "note": {"type": "string"}}}}, "steps": {"type": "array", "items": {"type": "string"}}, "tips": {"type": "string"}}};
const user = [
  'Auteur : ' + (meta.uploader || 'inconnu'),
  'Titre : ' + (meta.title || ''),
  '',
  '=== DESCRIPTION ===',
  caption.slice(0, 8000) || '(vide)',
  '',
  '=== TRANSCRIPTION AUDIO ===',
  transcript.slice(0, 12000) || '(vide)',
].join('\n');

return {
  json: {
    meta: { uploader: meta.uploader || null, thumbnail: meta.thumbnail || '', title: meta.title || '' },
    caption,
    transcript,
    gpt: {
      messages: [ { role: 'system', content: SYSTEM }, { role: 'user', content: user } ],
      response_format: { type: 'json_schema', json_schema: { name: 'recette', strict: true, schema: SCHEMA } },
    },
  },
};

// Transforme la réponse GPT en ligne de la table "recipes"
const job = $('Liste des imports').item.json;
const prep = $('Préparer le prompt').item.json;
const msg = $json.choices?.[0]?.message;
if (!msg || !msg.content) throw new Error('Réponse OpenAI vide : ' + JSON.stringify(msg || $json).slice(0, 300));
const r = JSON.parse(msg.content);
if (!r.is_recipe) throw new Error('NOT_RECIPE: la vidéo ne contient pas de recette exploitable');

const int = (v) => (Number.isFinite(v) && v >= 0 ? Math.round(v) : null);
const recipe = {
  id: job.id,                       // id de l'import = id de la recette (idempotent)
  household_id: job.household_id,
  title: String(r.title || 'Recette sans titre').slice(0, 200),
  description: r.description || '',
  category: r.category || 'plat',
  difficulty: r.difficulty || null,
  servings: Math.min(50, Math.max(1, int(r.servings) || 2)),
  prep_minutes: int(r.prep_minutes),
  cook_minutes: int(r.cook_minutes),
  diets: Array.isArray(r.diets) ? r.diets : [],
  ingredients: (r.ingredients || []).filter(i => i && i.name).map(i => ({
    name: String(i.name).trim(), quantity: Number.isFinite(i.quantity) ? i.quantity : null,
    unit: i.unit || '', section: i.section || 'autre', note: i.note || '',
  })),
  steps: (r.steps || []).map(s => String(s).trim()).filter(Boolean),
  tips: r.tips || '',
  source_url: job.url,
  source_author: prep.meta.uploader,
  source_caption: prep.caption,
  source_transcript: prep.transcript,
};
return { json: { recipe, thumbnail: prep.meta.thumbnail || '', image_path: job.household_id + '/' + job.id + '-ig.jpg' } };

// Ajoute le chemin de l'image seulement si l'upload a réussi
const b = $('Construire la recette').item.json;
const uploaded = !$json.error && ($json.Key || $json.Id || $json.key || $json.id);
return { json: { ...b.recipe, image_path: uploaded ? b.image_path : null } };

// Récupère l'import concerné et le message d'erreur
let job = null;
try { job = $('Liste des imports').item.json; } catch (e) {}
const raw = $json.error;
const msg = typeof raw === 'string' ? raw
  : (raw && (raw.message || raw.description)) || $json.message || JSON.stringify($json).slice(0, 500);
return { json: { p_id: job ? job.id : null, p_error: String(msg).slice(0, 1000), p_final: /NOT_RECIPE/.test(String(msg)) } };
